using System.Net;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Microsoft.Extensions.Logging;
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;
using TutorFlow.Infrastructure.Configuracion;
using TutorFlow.Pruebas.Soporte;

namespace TutorFlow.Api.Tests;

public sealed class FabricaApi : WebApplicationFactory<Program>
{
    public const string IpPorDefecto = "10.0.0.1";

    private readonly IReadOnlyDictionary<string, string?> _configuracion;
    private readonly IBaseConocimiento? _conocimiento;
    private readonly bool _reemplazarLlm;
    private readonly HttpMessageHandler? _manejadorHttp;
    private readonly bool _auditoriaReal;
    private readonly IClienteLlm? _clienteLlm;
    private readonly IReadOnlyDictionary<string, string?>? _variablesEntorno;
    private readonly Func<IClienteLlm, IClienteLlm>? _envolverLlm;

    public FabricaApi(
        ApiAcademicaDoble? api = null,
        ClienteLlmDoble? llm = null,
        IBaseConocimiento? conocimiento = null,
        IReadOnlyDictionary<string, string?>? configuracion = null,
        bool reemplazarLlm = true,
        HttpMessageHandler? manejadorHttp = null,
        bool conocimientoReal = false,
        bool auditoriaReal = false,
        IClienteLlm? clienteLlm = null,
        IReadOnlyDictionary<string, string?>? variablesEntorno = null,
        Func<IClienteLlm, IClienteLlm>? envolverLlm = null,
        RelojControlado? reloj = null)
    {
        Reloj = reloj ?? new RelojControlado();
        _variablesEntorno = variablesEntorno;
        _envolverLlm = envolverLlm;
        _clienteLlm = clienteLlm;
        Api = api ?? new ApiAcademicaDoble();
        Llm = llm ?? ClienteLlmDoble.Texto("Respuesta de prueba.");
        _conocimiento = ElegirConocimiento(conocimiento, conocimientoReal);
        _configuracion = configuracion ?? SinConfiguracion;
        _reemplazarLlm = reemplazarLlm;
        _manejadorHttp = manejadorHttp;
        _auditoriaReal = auditoriaReal;
    }

    private static readonly Dictionary<string, string?> SinConfiguracion = [];

    private static readonly object CandadoPorListenerDiagnosticoCompartidoDelPuntoDeEntrada = new();

    public new IServiceProvider Services
    {
        get
        {
            lock (CandadoPorListenerDiagnosticoCompartidoDelPuntoDeEntrada)
            {
                return base.Services;
            }
        }
    }

    private HttpClient ClienteConHostCreadoEnSerie()
    {
        _ = Services;
        return CreateClient();
    }

    public ApiAcademicaDoble Api { get; }

    public ClienteLlmDoble Llm { get; }

    public AuditoriaEnMemoria Auditoria { get; } = new();

    public RelojControlado Reloj { get; }

    public CapturaLogs Logs { get; } = new();

    private static IBaseConocimiento? ElegirConocimiento(IBaseConocimiento? conocimiento, bool real) =>
        real ? null : conocimiento ?? BaseConocimientoFalsa.Vigente();

    public static Dictionary<string, string?> Precios(string entrada, string salida) =>
        new Dictionary<string, string?> { ["LLM_PRECIO_ENTRADA"] = entrada, ["LLM_PRECIO_SALIDA"] = salida };

    public async Task<RespuestaApi> PreguntarAsync(string rol, string id, string pregunta, string ip = IpPorDefecto, IReadOnlyDictionary<string, string>? encabezados = null)
    {
        var cuerpo = JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } });
        return await EnviarAsync(HttpMethod.Post, "/api/asistente/preguntar", cuerpo, ip, encabezados);
    }

    public Task<RespuestaApi> PreguntarEstudianteAsync(string id, string pregunta, string ip = IpPorDefecto) =>
        PreguntarAsync("estudiante", id, pregunta, ip);

    public Task<RespuestaApi> PreguntarCoordinadorAsync(string id, string pregunta, string ip = IpPorDefecto) =>
        PreguntarAsync("coordinador", id, pregunta, ip);

    public async Task<RespuestaApi> EnviarAsync(HttpMethod metodo, string ruta, string? cuerpo, string ip = IpPorDefecto, IReadOnlyDictionary<string, string>? encabezados = null)
    {
        using var cliente = ClienteConHostCreadoEnSerie();
        using var peticion = new HttpRequestMessage(metodo, ruta);
        peticion.Headers.Add(FiltroIpRemota.Encabezado, ip);
        foreach (var (clave, valor) in encabezados ?? new Dictionary<string, string>())
        {
            peticion.Headers.TryAddWithoutValidation(clave, valor);
        }

        if (cuerpo is not null)
        {
            peticion.Content = new StringContent(cuerpo, Encoding.UTF8, "application/json");
        }

        using var respuesta = await cliente.SendAsync(peticion);
        var bytes = await respuesta.Content.ReadAsByteArrayAsync();
        return new RespuestaApi(respuesta.StatusCode, bytes, respuesta.Headers, respuesta.Content.Headers);
    }

    public async Task<RespuestaApi> EnviarConTipoAsync(string cuerpo, string? tipoContenido, string ip = IpPorDefecto, IReadOnlyDictionary<string, string>? encabezados = null)
    {
        using var cliente = ClienteConHostCreadoEnSerie();
        using var peticion = new HttpRequestMessage(HttpMethod.Post, "/api/asistente/preguntar");
        peticion.Headers.Add(FiltroIpRemota.Encabezado, ip);
        foreach (var (clave, valor) in encabezados ?? new Dictionary<string, string>())
        {
            peticion.Headers.TryAddWithoutValidation(clave, valor);
        }

        peticion.Content = new ByteArrayContent(Encoding.UTF8.GetBytes(cuerpo));
        if (tipoContenido is not null)
        {
            peticion.Content.Headers.TryAddWithoutValidation("Content-Type", tipoContenido);
        }

        using var respuesta = await cliente.SendAsync(peticion);
        var bytes = await respuesta.Content.ReadAsByteArrayAsync();
        return new RespuestaApi(respuesta.StatusCode, bytes, respuesta.Headers, respuesta.Content.Headers);
    }

    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        builder.UseEnvironment("Production");
        builder.UseContentRoot(Path.Combine(DatosReferencia.RutaRepositorio(), "backend", "src", "TutorFlow.Api"));
        foreach (var (clave, valor) in _configuracion)
        {
            builder.UseSetting(clave, valor);
        }

        builder.ConfigureAppConfiguration((_, configuracion) => configuracion.AddInMemoryCollection(_configuracion));
        builder.ConfigureLogging(logging =>
        {
            logging.SetMinimumLevel(LogLevel.Trace);
            logging.AddProvider(Logs);
        });
        builder.ConfigureTestServices(Reemplazar);
    }

    private void Reemplazar(IServiceCollection servicios)
    {
        servicios.RemoveAll<IApiAcademica>();
        servicios.RemoveAll<IReloj>();
        servicios.RemoveAll<TimeProvider>();
        servicios.AddSingleton<TimeProvider>(Reloj.Tiempo);
        if (_variablesEntorno is not null)
        {
            servicios.RemoveAll<IVariablesEntorno>();
            servicios.AddSingleton<IVariablesEntorno>(new VariablesEntornoFijas(_variablesEntorno));
        }

        servicios.AddSingleton<IApiAcademica>(Api);
        servicios.AddSingleton<IReloj>(Reloj);
        if (!_auditoriaReal)
        {
            servicios.RemoveAll<IAuditoria>();
            servicios.AddSingleton<IAuditoria>(Auditoria);
        }

        servicios.AddSingleton<Microsoft.AspNetCore.Hosting.IStartupFilter, FiltroIpRemota>();
        if (_conocimiento is not null)
        {
            servicios.RemoveAll<IBaseConocimiento>();
            servicios.AddSingleton(_conocimiento);
        }

        if (_manejadorHttp is not null)
        {
            servicios.ConfigureHttpClientDefaults(b => b.ConfigurePrimaryHttpMessageHandler(() => _manejadorHttp));
        }

        ReemplazarLlm(servicios);
    }

    private void ReemplazarLlm(IServiceCollection servicios)
    {
        if (_reemplazarLlm)
        {
            servicios.RemoveAll<IClienteLlm>();
            servicios.AddSingleton(_clienteLlm ?? Llm);
        }

        if (_envolverLlm is not null)
        {
            EnvolverLlm(servicios, _envolverLlm);
        }
    }

    private static void EnvolverLlm(IServiceCollection servicios, Func<IClienteLlm, IClienteLlm> envolver)
    {
        var original = servicios.Last(d => d.ServiceType == typeof(IClienteLlm));
        servicios.Remove(original);
        servicios.Add(ServiceDescriptor.Describe(typeof(IClienteLlm), proveedor => envolver(ResolverLlm(proveedor, original)), original.Lifetime));
    }

    private static IClienteLlm ResolverLlm(IServiceProvider proveedor, ServiceDescriptor descriptor) =>
        descriptor.ImplementationInstance as IClienteLlm
        ?? descriptor.ImplementationFactory?.Invoke(proveedor) as IClienteLlm
        ?? (IClienteLlm)ActivatorUtilities.CreateInstance(proveedor, descriptor.ImplementationType!);
}

public sealed record RespuestaApi(HttpStatusCode Codigo, byte[] Bytes, HttpResponseHeaders Encabezados, HttpContentHeaders EncabezadosContenido)
{
    public int Estado => (int)Codigo;

    public string Texto => Encoding.UTF8.GetString(Bytes);

    public JsonElement Json => JsonDocument.Parse(Bytes).RootElement.Clone();

    public string? TipoContenido => EncabezadosContenido.ContentType?.ToString();

    public string Respuesta => Json.GetProperty("respuesta").GetString()!;

    public int Tokens => Json.GetProperty("tokens").GetInt32();

    public decimal CostoUsd => Json.GetProperty("costoUsd").GetDecimal();

    public bool UsoDatosEstudiante => Json.GetProperty("usoDatosEstudiante").GetBoolean();

    public IReadOnlyList<string> Citas =>
        Json.GetProperty("citas").EnumerateArray()
            .Select(c => $"{c.GetProperty("documento").GetString()} · {c.GetProperty("seccion").GetString()}")
            .ToList();

    public bool TieneEncabezado(string nombre) =>
        Encabezados.Contains(nombre) || EncabezadosContenido.Contains(nombre);

    public string? Encabezado(string nombre) =>
        Encabezados.TryGetValues(nombre, out var valores) ? valores.FirstOrDefault() : null;
}
using TutorFlow.Pruebas.Soporte;
using System.Text.Json;
using System.Text.RegularExpressions;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Api.Tests.Dobles;

public delegate RespuestaLlm GuionLlm(SolicitudLlm solicitud, int numeroLlamada);

public sealed partial class ClienteLlmDoble : IClienteLlm
{
    public const string ParametroEstudianteId = "estudianteId";
    public static readonly UsoTokens UsoPorDefecto = new(100, 20);

    private readonly GuionLlm _guion;
    private readonly List<SolicitudLlm> _solicitudes = [];
    private readonly Lock _candado = new();

    public ClienteLlmDoble(GuionLlm guion)
    {
        _guion = guion;
    }

    public int Llamadas
    {
        get
        {
            lock (_candado)
            {
                return _solicitudes.Count;
            }
        }
    }

    public IReadOnlyList<SolicitudLlm> Solicitudes
    {
        get
        {
            lock (_candado)
            {
                return [.. _solicitudes];
            }
        }
    }

    public static ClienteLlmDoble Texto(string texto, UsoTokens? uso = null) =>
        new((_, _) => new RespuestaLlm(texto, [], uso ?? UsoPorDefecto, false));

    public static ClienteLlmDoble Rechaza() =>
        new((_, _) => new RespuestaLlm(null, [], UsoPorDefecto, true));

    public static ClienteLlmDoble Falla(Exception excepcion) =>
        new((_, _) => throw excepcion);

    public static ClienteLlmDoble QueNuncaResponde() =>
        new((_, _) => throw new TaskCanceledException("llm sin respuesta"));

    public static ClienteLlmDoble ConsultaDatos(string? estudianteIdParaCoordinador = null, Func<SolicitudLlm, string>? redactar = null, UsoTokens? uso = null)
    {
        var redactor = redactar ?? EcoDeHerramientas;
        var consumo = uso ?? UsoPorDefecto;
        return new ClienteLlmDoble((solicitud, n) => ConsultarOResponder(solicitud, n, estudianteIdParaCoordinador, redactor, consumo));
    }

    private static RespuestaLlm ConsultarOResponder(SolicitudLlm solicitud, int numero, string? estudianteId, Func<SolicitudLlm, string> redactor, UsoTokens consumo)
    {
        var llamadas = numero == 0 ? LlamarTodas(solicitud.Herramientas, estudianteId) : [];
        return llamadas.Count > 0
            ? new RespuestaLlm(null, llamadas, consumo, false)
            : new RespuestaLlm(redactor(solicitud), [], consumo, false);
    }

    public static ClienteLlmDoble PideEstudiante(string estudianteId, UsoTokens? uso = null) =>
        new((solicitud, n) =>
        {
            var herramienta = ElegirHerramienta(solicitud.Herramientas);
            return n == 0 && herramienta is not null
                ? new RespuestaLlm(null, [Llamada("pide-1", herramienta.Nombre, JsonSerializer.Serialize(new Dictionary<string, string> { [ParametroEstudianteId] = estudianteId }))], uso ?? UsoPorDefecto, false)
                : new RespuestaLlm("Sin datos", [], uso ?? UsoPorDefecto, false);
        });

    public static ClienteLlmDoble PideHerramientaSinParar() =>
        new((solicitud, n) => new RespuestaLlm(null, [Llamada($"sin-parar-{n}", solicitud.Herramientas[0].Nombre, "{}")], UsoPorDefecto, false));

    public static ClienteLlmDoble PideHerramientaVariasVecesEnUnaRespuesta(int veces) =>
        new((solicitud, _) => new RespuestaLlm(
            null,
            Enumerable.Range(0, veces).Select(i => Llamada($"lote-{i}", solicitud.Herramientas[0].Nombre, "{}")).ToList(),
            UsoPorDefecto,
            false));

    public static IReadOnlyList<string> ParametrosDeId(SolicitudLlm solicitud) =>
        solicitud.Herramientas
            .SelectMany(h => h.Parametros)
            .Select(p => p.Nombre)
            .Where(n => ParametroDeIdRegex().IsMatch(n))
            .ToList();

    public static string EcoDeHerramientas(SolicitudLlm solicitud) =>
        string.Join("\n", solicitud.Mensajes.Where(m => m.Rol == RolMensaje.Herramienta).Select(m => m.Contenido));

    public Task<RespuestaLlm> CompletarAsync(SolicitudLlm solicitud, CancellationToken cancellationToken)
    {
        int numero;
        lock (_candado)
        {
            numero = _solicitudes.Count;
            _solicitudes.Add(solicitud);
        }

        var respuesta = _guion(solicitud, numero);
        return Task.FromResult(respuesta with { Uso = respuesta.Uso with { Entrada = ConsumoRealista.Reportados(solicitud) } });
    }

    private static List<LlamadaHerramienta> LlamarTodas(IReadOnlyList<HerramientaLlm> herramientas, string? estudianteId) =>
        herramientas
            .Where(h => estudianteId is not null || !h.Parametros.Any(p => p.Nombre == ParametroEstudianteId))
            .Select(h => Llamada($"llamada-{h.Nombre}", h.Nombre, ArgumentosPara(h, estudianteId)))
            .ToList();

    private static string ArgumentosPara(HerramientaLlm herramienta, string? estudianteId) =>
        herramienta.Parametros.Any(p => p.Nombre == ParametroEstudianteId)
            ? $$"""{"{{ParametroEstudianteId}}":"{{estudianteId}}"}"""
            : "{}";

    private static HerramientaLlm? ElegirHerramienta(IReadOnlyList<HerramientaLlm> herramientas) =>
        herramientas.FirstOrDefault(h => h.Parametros.Any(p => p.Nombre == ParametroEstudianteId)) ?? (herramientas.Count > 0 ? herramientas[0] : null);

    private static LlamadaHerramienta Llamada(string id, string nombre, string argumentosJson) => new(id, nombre, argumentosJson);

    [GeneratedRegex("id$|estudiante|usuario|alumno", RegexOptions.IgnoreCase)]
    private static partial Regex ParametroDeIdRegex();
}
using System.Collections.Concurrent;
using TutorFlow.Core.Academico;
using TutorFlow.Core.Asistente;
using TutorFlow.Pruebas.Soporte;

namespace TutorFlow.Api.Tests.Dobles;

public sealed class ApiAcademicaDoble : IApiAcademica
{
    private readonly DatosAcademicos _datos;
    private readonly ConcurrentQueue<string> _llamadas = new();

    public ApiAcademicaDoble(DatosAcademicos? datos = null)
    {
        _datos = datos ?? DatosReferencia.Cargar();
    }

    public Func<string, CancellationToken, Task>? Interceptor { get; set; }

    public IReadOnlyList<string> Llamadas => [.. _llamadas];

    public int LecturasDatosDe(string estudianteId) =>
        Llamadas.Count(l => l == $"ObtenerNotas:{estudianteId}" || l == $"ObtenerAsistencia:{estudianteId}");

    public static ApiAcademicaDoble Caida() => new() { Interceptor = (_, _) => throw new HttpRequestException("api academica caida en http://localhost:4000") };

    public static ApiAcademicaDoble QueNuncaResponde(RelojControlado reloj) => new() { Interceptor = (_, ct) => reloj.Pausar(Timeout.InfiniteTimeSpan, ct) };

    public async Task<Estudiante?> ObtenerEstudianteAsync(string id, CancellationToken cancellationToken)
    {
        await Registrar("ObtenerEstudiante", id, cancellationToken);
        return _datos.Estudiantes.FirstOrDefault(e => e.Id == id);
    }

    public async Task<Coordinador?> ObtenerCoordinadorAsync(string id, CancellationToken cancellationToken)
    {
        await Registrar("ObtenerCoordinador", id, cancellationToken);
        return _datos.Coordinadores.FirstOrDefault(c => c.Id == id);
    }

    public async Task<IReadOnlyList<NotasAsignatura>> ObtenerNotasAsync(string estudianteId, CancellationToken cancellationToken)
    {
        await Registrar("ObtenerNotas", estudianteId, cancellationToken);
        return _datos.NotasDe(estudianteId);
    }

    public async Task<IReadOnlyList<AsistenciaAsignatura>> ObtenerAsistenciaAsync(string estudianteId, CancellationToken cancellationToken)
    {
        await Registrar("ObtenerAsistencia", estudianteId, cancellationToken);
        return _datos.AsistenciaDe(estudianteId);
    }

    public async Task<IReadOnlyList<Estudiante>> ObtenerEstudiantesDeProgramaAsync(string programaId, CancellationToken cancellationToken)
    {
        await Registrar("ObtenerEstudiantesDePrograma", programaId, cancellationToken);
        return _datos.Estudiantes.Where(e => e.ProgramaId == programaId).ToList();
    }

    public async Task<IReadOnlyList<Programa>> ObtenerProgramasAsync(CancellationToken cancellationToken)
    {
        await Registrar("ObtenerProgramas", string.Empty, cancellationToken);
        return _datos.Programas;
    }

    private async Task Registrar(string metodo, string argumento, CancellationToken cancellationToken)
    {
        _llamadas.Enqueue($"{metodo}:{argumento}");
        if (Interceptor is not null)
        {
            await Interceptor(metodo, cancellationToken);
        }
    }
}
using System.Text.Json;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Api.Tests;

public static class Afirmaciones
{
    public const string CitaNegativa = "reglamento_academico_2025.md · Artículo 22";

    private static readonly string[] PropiedadesDeSalida = ["respuesta", "citas", "usoDatosEstudiante", "tokens", "costoUsd"];
    private static readonly string[] PropiedadesDeCita = ["documento", "seccion"];
    private static readonly string[] FragmentosInternos = ["StackTrace", "   at ", "System.", "Exception", "Microsoft.", "TutorFlow.", "localhost:4000", ".cs:line"];

    public static void SalidaDelContrato(RespuestaApi respuesta)
    {
        var json = respuesta.Json;
        Assert.Equal(JsonValueKind.Object, json.ValueKind);
        Assert.Equal(PropiedadesDeSalida.Order(), json.EnumerateObject().Select(p => p.Name).Order());
        Assert.Equal(JsonValueKind.String, json.GetProperty("respuesta").ValueKind);
        Assert.Equal(JsonValueKind.Array, json.GetProperty("citas").ValueKind);
        Assert.True(json.GetProperty("usoDatosEstudiante").ValueKind is JsonValueKind.True or JsonValueKind.False);
        Assert.True(json.GetProperty("tokens").TryGetInt32(out var tokens) && tokens >= 0);
        Assert.True(json.GetProperty("costoUsd").TryGetDecimal(out var costo) && costo >= 0);
        foreach (var cita in json.GetProperty("citas").EnumerateArray())
        {
            Assert.Equal(PropiedadesDeCita.Order(), cita.EnumerateObject().Select(p => p.Name).Order());
            Assert.Equal(JsonValueKind.String, cita.GetProperty("documento").ValueKind);
            Assert.Equal(JsonValueKind.String, cita.GetProperty("seccion").ValueKind);
        }
    }

    public static void SinInformacion(RespuestaApi respuesta)
    {
        Assert.Equal(200, respuesta.Estado);
        SalidaDelContrato(respuesta);
        Assert.Equal(Textos.SinInformacion, respuesta.Respuesta);
        Assert.Empty(respuesta.Citas);
        Assert.False(respuesta.UsoDatosEstudiante);
    }

    public static void SinInformacionSinLlm(RespuestaApi respuesta, FabricaApi fabrica)
    {
        SinInformacion(respuesta);
        Assert.Equal(0, respuesta.Tokens);
        Assert.Equal(0m, respuesta.CostoUsd);
        Assert.Equal(0, fabrica.Llm.Llamadas);
        Assert.DoesNotContain(fabrica.Api.Llamadas, l => l.StartsWith("ObtenerNotas", StringComparison.Ordinal) || l.StartsWith("ObtenerAsistencia", StringComparison.Ordinal));
        Assert.Equal(ResultadoAuditoria.SinInformacion, Assert.Single(fabrica.Auditoria.Eventos).Resultado);
    }

    public static void SinInformacionTrasLlm(RespuestaApi respuesta, FabricaApi fabrica)
    {
        SinInformacion(respuesta);
        Assert.Equal(1, fabrica.Llm.Llamadas);
        Assert.True(respuesta.Tokens > 0);
        Assert.Equal(ResultadoAuditoria.SinInformacion, Assert.Single(fabrica.Auditoria.Eventos).Resultado);
    }

    public static void Negativa(RespuestaApi respuesta, string rol)
    {
        Assert.Equal(403, respuesta.Estado);
        SalidaDelContrato(respuesta);
        Assert.Equal(rol == "estudiante" ? Textos.NegativaEstudiante : Textos.NegativaCoordinador, respuesta.Respuesta);
        Assert.Equal([CitaNegativa], respuesta.Citas);
        Assert.False(respuesta.UsoDatosEstudiante);
        Assert.Equal(0, respuesta.Tokens);
        Assert.Equal(0m, respuesta.CostoUsd);
    }

    public static void ProblemDetails(RespuestaApi respuesta, int estado)
    {
        Assert.Equal(estado, respuesta.Estado);
        Assert.Contains("application/problem+json", respuesta.TipoContenido, StringComparison.OrdinalIgnoreCase);
        var json = respuesta.Json;
        Assert.Equal(estado, json.GetProperty("status").GetInt32());
        Assert.Equal(JsonValueKind.String, json.GetProperty("title").ValueKind);
        SinDetallesInternos(respuesta);
    }

    public static void SinDetallesInternos(RespuestaApi respuesta)
    {
        foreach (var fragmento in FragmentosInternos)
        {
            Assert.DoesNotContain(fragmento, respuesta.Texto, StringComparison.Ordinal);
        }
    }

    public static void SinEncabezadoCorsComodin(RespuestaApi respuesta)
    {
        var valor = respuesta.Encabezado("Access-Control-Allow-Origin");
        Assert.True(valor is null || (valor != "*" && !valor.Contains("evil.example", StringComparison.Ordinal)));
    }
}

