    [InlineData("¿Cuál es el promedio de Valentina Castro?")]
    [InlineData(PreguntaQ10Seis)]
    [InlineData("¿Quiénes están en prueba académica?")]
    [Trait("CA", "CA-19")]
    [Trait("ESC", "ESC-190")]
    [Trait("COMP", "COMP-08")]
