    public void ESC_179_y_Los_ejemplos_2_y_4_del_coordinador_van_en_tercera_persona()
    {
        var casos = PartesDelPrompt.CasosDeEjemplo(ConstructorPrompts.PromptSistema(Rol.Coordinador, null));

        Assert.Equal(4, casos.Count);
