        var resultado = await escenario.PreguntarAsync(Coord02, PreguntaPerdidas);

        SalidasVerificadas.AfirmarEstadoNoVerificado(resultado, escenario, usoDatos: true);
    }

    [Theory]
    [MemberData(nameof(BloquesFielesOSinForma))]
